```
FILE *oldTodoFile;
oldTodoFile = fopen("./todo.txt", "r");

FILE *todoFile;
todoFile = fopen("./todo2.txt", "w");
int lineNumber = 0;
int len;
char line[4096];

if (oldTodoFile != NULL) {
    while (fgets(line, sizeof line, oldTodoFile)) {
        len = strlen(line);
        if (len && (line[len - 1] != '\n')) {} else {
