### Top Answer: Sure. This could be done easily with class decorators:

```
# vehicle.py
class Vehicle(object):
    pass

_vehicle_types = []

def vehicle_type(cls):
    _vehicle_types.append(cls)

def make_vehicle(type_):
    for vt in _vehicle_types:
        if vt.type_ == type_:
            return vt()
    raise ValueError('No vehicle of type "{}" exists'.format(type_))

# car.py
import vehicle

@vehicle.vehicle_type
class Car(vehicle.Vehicle):
    type_ = 'car'

# bus.py
import vehicle

@vehicle.vehicle_type
class Bus(vehicle.Vehicle):
    type_ = 'bus'

